class Solution {
  public double minTime(int n, int k, int m, int[] time, double[] mul) {
    int full = (1 << n) - 1;
    double[] maxT = new double[full + 1];
    for (int mask = 1; mask <= full; mask++) {
      int low = Integer.numberOfTrailingZeros(mask);
      maxT[mask] = Math.max(maxT[mask & (mask - 1)], time[low]);
    }
    // state = ((mask * m + stage) * 2 + side); mask = people still at the base camp
    int total = (full + 1) * m * 2;
    double[] dist = new double[total];
    java.util.Arrays.fill(dist, Double.MAX_VALUE);
    java.util.PriorityQueue<double[]> pq =
        new java.util.PriorityQueue<>((a, b) -> Double.compare(a[0], b[0]));
    dist[(full * m) * 2] = 0;
    pq.add(new double[] {0, (full * m) * 2});
    while (!pq.isEmpty()) {
      double[] top = pq.poll();
      int state = (int) top[1];
      if (top[0] > dist[state]) continue;
      int side = state & 1, rest = state >> 1, stage = rest % m, mask = rest / m;
      if (mask == 0) return top[0];
      if (side == 0) {
        for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
          if (Integer.bitCount(sub) > k) continue;
          double d = maxT[sub] * mul[stage];
          int ns = (stage + (int) Math.floor(d)) % m;
          int nm = mask ^ sub;
          int nstate = ((nm * m + ns) * 2) + 1;
          if (top[0] + d < dist[nstate]) {
            dist[nstate] = top[0] + d;
            pq.add(new double[] {dist[nstate], nstate});
          }
        }
      } else {
        for (int r = 0; r < n; r++) {
          if ((mask >> r & 1) != 0) continue;
          double d = time[r] * mul[stage];
          int ns = (stage + (int) Math.floor(d)) % m;
          int nstate = (((mask | 1 << r) * m + ns) * 2);
          if (top[0] + d < dist[nstate]) {
            dist[nstate] = top[0] + d;
            pq.add(new double[] {dist[nstate], nstate});
          }
        }
      }
    }
    return -1;
  }
}
